"""Safety layer: disclaimers and crisis detection.

This runs BEFORE any model call. If an entry looks like it may involve
self-harm or suicide, MindMosaic does not attempt CBT reframing at all and
instead shows supportive text and a pointer to real help.
"""
import re

DISCLAIMER = (
    "MindMosaic is a self-reflection tool, not a medical device or a therapist. "
    "It cannot diagnose, treat or replace professional care. The suggestions are "
    "generated by a small local AI model and can be wrong. If you are struggling, "
    "please talk to a qualified mental health professional or someone you trust."
)

CRISIS_MESSAGE = (
    "What you wrote sounds really heavy, and I'm glad you put it into words. "
    "I'm not able to help with this safely, and you deserve real support from a person. "
    "If you might hurt yourself or are in immediate danger, please contact your local "
    "emergency number now, or go to the nearest emergency room. You can also find "
    "helplines in your country at https://findahelpline.com. If you can, reach out to "
    "someone you trust and tell them how you're feeling today."
)

# Deliberately broad: a false alarm shows a caring message, a miss could hurt.
_CRISIS_PATTERNS = [
    r"\bkill (myself|me)\b",
    r"\bsuicid(e|al)\b",
    r"\bend (my|it all|my life)\b",
    r"\bwant(ed)? to die\b",
    r"\bwish i (was|were) dead\b",
    r"\bbetter off (dead|without me)\b",
    r"\bno reason to (live|go on)\b",
    r"\bdon'?t want to (live|be alive|exist|be here)\b",
    r"\b(hurt|harm|cut|injure)(ing)? myself\b",
    r"\bself[- ]?harm\b",
    r"\btake my own life\b",
    r"\bcan'?t go on\b",
]
_CRISIS_RE = re.compile("|".join(_CRISIS_PATTERNS), re.IGNORECASE)


def detect_crisis(text: str) -> bool:
    """Return True if the text matches any crisis phrase."""
    return bool(_CRISIS_RE.search(text or ""))
